"""Frozen, additive SQLite S4 schema; independent of future ORM changes."""

names = ['public_entries', 'public_revisions', 'public_entry_events', 'public_interaction_events']

statements = [
    "CREATE TABLE public_entries (\n\ttool_id VARCHAR(36) NOT NULL, \n\tgithub_repo_id INTEGER NOT NULL, \n\tpublic_id VARCHAR(36) NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tdraft_revision_id VARCHAR(36), \n\tpublished_revision_id VARCHAR(36), \n\tfirst_published_at FLOAT, \n\tupdated_at FLOAT NOT NULL, \n\twithdrawn_at FLOAT, \n\towner_id VARCHAR(36) NOT NULL, \n\tdata_mode VARCHAR(8) NOT NULL, \n\tid VARCHAR(36) NOT NULL, \n\tcreated_at FLOAT NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (data_mode, github_repo_id), \n\tUNIQUE (data_mode, tool_id), \n\tCHECK (state IN ('draft','published','withdrawn')), \n\tCHECK (state != 'published' OR published_revision_id IS NOT NULL), \n\tFOREIGN KEY(id, draft_revision_id) REFERENCES public_revisions (entry_id, id), \n\tFOREIGN KEY(id, published_revision_id) REFERENCES public_revisions (entry_id, id), \n\tFOREIGN KEY(tool_id) REFERENCES tools (id), \n\tUNIQUE (public_id), \n\tFOREIGN KEY(owner_id) REFERENCES creators (id)\n)",
    'CREATE INDEX ix_public_entries_owner_id ON public_entries (owner_id)',
    'CREATE TABLE public_revisions (\n\tentry_id VARCHAR(36) NOT NULL, \n\tversion INTEGER NOT NULL, \n\tcontent_json JSON NOT NULL, \n\tcontent_hash VARCHAR(64) NOT NULL, \n\tsource_snapshot_id VARCHAR(36) NOT NULL, \n\tanalysis_id VARCHAR(36) NOT NULL, \n\treviewed_at FLOAT, \n\treviewed_by VARCHAR(36), \n\tpublished_at FLOAT, \n\tid VARCHAR(36) NOT NULL, \n\tcreated_at FLOAT NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (entry_id, version), \n\tUNIQUE (entry_id, id), \n\tFOREIGN KEY(entry_id) REFERENCES public_entries (id), \n\tFOREIGN KEY(source_snapshot_id) REFERENCES source_snapshots (id), \n\tFOREIGN KEY(analysis_id) REFERENCES analyses (id), \n\tFOREIGN KEY(reviewed_by) REFERENCES creators (id)\n)',
    "CREATE TABLE public_entry_events (\n\tentry_id VARCHAR(36) NOT NULL, \n\trevision_id VARCHAR(36) NOT NULL, \n\towner_id VARCHAR(36) NOT NULL, \n\tkind VARCHAR(16) NOT NULL, \n\tid VARCHAR(36) NOT NULL, \n\tcreated_at FLOAT NOT NULL, \n\tPRIMARY KEY (id), \n\tCHECK (kind IN ('publish','update','withdraw')), \n\tFOREIGN KEY(entry_id) REFERENCES public_entries (id), \n\tFOREIGN KEY(revision_id) REFERENCES public_revisions (id), \n\tFOREIGN KEY(owner_id) REFERENCES creators (id)\n)",
    "CREATE TABLE public_interaction_events (\n\tevent_id VARCHAR(36) NOT NULL, \n\tentry_id VARCHAR(36) NOT NULL, \n\trevision_id VARCHAR(36) NOT NULL, \n\tkind VARCHAR(16) NOT NULL, \n\tid VARCHAR(36) NOT NULL, \n\tcreated_at FLOAT NOT NULL, \n\tPRIMARY KEY (id), \n\tCHECK (kind IN ('intro_open','github_click')), \n\tUNIQUE (event_id), \n\tFOREIGN KEY(entry_id) REFERENCES public_entries (id), \n\tFOREIGN KEY(revision_id) REFERENCES public_revisions (id)\n)",
]
